{
  "$schema": "https://opencode.ai/config.json",
  "update": "auto",
  "share": "manual",
  "formatter": {},
  "lsp": {},
  "experimental": {
    "todo": false,
    "subagent_depth": 1,
    "background_compaction": true
  },
  "mcp": {
    "servers": {
      "context7": {
        "type": "remote",
        "url": "https://mcp.context7.com/mcp",
        "headers": {
          "CONTEXT7_API_KEY": "{env:C7_KEY}"
        },
        "oauth": false,
        "disabled": false
      },
      "github": {
        "type": "remote",
        "url": "https://api.githubcopilot.com/mcp/",
        "oauth": false,
        "headers": {
          "Authorization": "Bearer {env:GITHUB_PERSONAL_ACCESS_TOKEN}"
        },
        "disabled": false
      }
    }
  },
  "instructions": [],
  "providers": {},
  "plugins": [],
  "agents": {},
  "commands": {},
  "permissions": [
    { "action": "*", "resource": "*", "effect": "allow" }
  ]
}
